// Valida shared secret (se configurado) e traduz o payload Chatwoot
// para o shape que a Avisa API espera.
//
// AJUSTE_AQUI: endpoint exato e nome de campos (number/jid, message/text, etc.)
// variam entre versões da Avisa. Ajuste depois do primeiro POST de teste.
const expected = $env.SYNAPSEOS_WEBHOOK_SECRET;
const headers = $input.first().json.headers || {};
const received = headers['x-synapseos-signature'] || headers['X-Synapseos-Signature'] || '';
if (expected && expected !== received) {
  throw new Error('Invalid X-Synapseos-Signature');
}

const body = $input.first().json.body || {};
// Avisa espera número sem o '+' (ex: 5511999999999).
const number = String(body.to || '').replace(/[^0-9]/g, '');
const type = body.type || 'text';
const payload = body.payload || {};

let avisaBody;
switch (type) {
  case 'text':
    avisaBody = { number, message: payload.text || '' };
    break;
  case 'image':
    avisaBody = { number, url: payload.url, caption: payload.caption || '' };
    break;
  case 'audio':
    avisaBody = { number, url: payload.url };
    break;
  case 'video':
    avisaBody = { number, url: payload.url, caption: payload.caption || '' };
    break;
  case 'document':
    avisaBody = { number, url: payload.url, caption: payload.caption || '' };
    break;
  default:
    avisaBody = { number, message: JSON.stringify(payload) };
}

// AJUSTE_AQUI: path final da API Avisa por tipo de mensagem.
const endpointMap = {
  text: '/send-message',
  image: '/send-image',
  audio: '/send-audio',
  video: '/send-video',
  document: '/send-document'
};
const endpoint = endpointMap[type] || '/send-message';

return [{
  json: {
    avisa_url: `${$env.SYNAPSEOS_AVISA_BASE_URL || 'https://www.avisaapi.com.br/api'}${endpoint}`,
    avisa_body: avisaBody,
    chatwoot_message_id: body.chatwoot_message_id,
    chatwoot_conversation_id: body.chatwoot_conversation_id
  }
}];
